// ============ ONDE COLOCAR AS CHAVES (SO AQUI) ============
const CFG = {
  NASA_API_KEY: "COLE_AQUI_SUA_CHAVE_NASA",
  GROQ_API_KEY: "COLE_AQUI_SUA_CHAVE_GROQ (gsk_...)",
  WEBHOOK_SECRET: "COLE_AQUI_O_MESMO_VALOR_DE_N8N_WEBHOOK_SECRET_DO_LOVABLE",
  GROQ_MODEL: "llama-3.3-70b-versatile",
  // Se esta URL do DONKI nao responder, troque por: https://api.nasa.gov/DONKI
  DONKI_BASE: "https://ccmc.gsfc.nasa.gov/DONKI-API/get",
  // Cada Sol da campanha aponta para uma data da Terra (muda APOD, DONKI e a foto). Edite livremente.
  SOL_DATES: { 1: "2024-05-08", 2: "2024-05-09", 3: "2024-05-10", 4: "2024-05-11", 5: "2024-05-12" }
};
// ============================================================

const inp = $input.first().json;
const headers = inp.headers || {};
if (CFG.WEBHOOK_SECRET && !CFG.WEBHOOK_SECRET.startsWith("COLE_AQUI") && headers["x-api-key"] !== CFG.WEBHOOK_SECRET) {
  throw new Error("unauthorized");
}
const isNasa = !!(inp.query && inp.query.sol !== undefined);
const addDays = (d, n) => { const t = new Date(d + "T00:00:00Z"); t.setUTCDate(t.getUTCDate() + n); return t.toISOString().slice(0, 10); };
let sol = 1, earth_date = CFG.SOL_DATES[1];
if (isNasa) {
  sol = Math.min(5, Math.max(1, parseInt(inp.query.sol, 10) || 1));
  earth_date = CFG.SOL_DATES[sol];
}
return [{ json: { ...inp, cfg: CFG, is_nasa: isNasa, sol, earth_date, d_prev: addDays(earth_date, -1), d_next: addDays(earth_date, 1) } }];

const cfgItem = $('CONFIG').first().json;
const sol = cfgItem.sol, date = cfgItem.earth_date;
const all = (name) => { try { return $(name).all().map(i => i.json).filter(j => j && !j.error); } catch (e) { return []; } };

// ---- APOD (imagem astronomica do dia, muda por Sol) ----
let apod = null;
{
  let r = all("APOD")[0];
  if (Array.isArray(r)) r = r[0];
  if (r) {
    const t = (v) => (v && typeof v === "object" && "rendered" in v) ? v.rendered : v;
    const url = r.hdurl || r.url || (r.acf && (r.acf.hdurl || r.acf.url)) || null;
    if (url && String(url).startsWith("https://")) {
      apod = {
        date: r.date || date,
        title: String(t(r.title) || "Astronomy Picture of the Day"),
        explanation: String(t(r.explanation) || t(r.content) || "").replace(/<[^>]+>/g, "").slice(0, 600),
        media_type: r.media_type === "video" ? "video" : "image",
        url, copyright: r.copyright || undefined
      };
    }
  }
}

// ---- DONKI: erupcao solar (maior classe do dia) ----
let flare = null;
{
  const order = { A: 0, B: 1, C: 2, M: 3, X: 4 };
  let best = null;
  for (const f of all("DONKI FLR")) {
    const m = /^([ABCMX])(\d+(?:\.\d+)?)/.exec(String(f.classType || ""));
    if (!m) continue;
    const cand = { class: m[1], magnitude: parseFloat(m[2]), source: "DONKI/FLR" };
    if (!best || order[cand.class] > order[best.class] || (cand.class === best.class && cand.magnitude > best.magnitude)) best = cand;
  }
  flare = best;
}

// ---- DONKI: CME (maior velocidade) ----
let cme = null;
{
  const speeds = all("DONKI CME").map(c => Number(c.speed)).filter(Number.isFinite);
  if (speeds.length) cme = { speed_kms: Math.max(...speeds), source: "DONKI/CMEAnalysis" };
}

// ---- DONKI: simulacao WSA-Enlil -> impacto em Marte ----
let mars_impact = null;
{
  const sims = all("DONKI WSA-Enlil");
  if (sims.length || cme) {
    let level = "none";
    for (const s of sims) for (const imp of (s.impactList || [])) {
      if (String(imp.location || "").toLowerCase() === "mars") {
        if (imp.isGlancingBlow) { if (level === "none") level = "glancing_blow"; } else level = "direct";
      }
    }
    mars_impact = { level, source: "DONKI/WSAEnlilSimulations" };
  }
}

// ---- InSight (dados historicos: a missao acabou em 2022) ----
let weather = null, wind = null, insight_sol = null;
{
  const ins = all("InSight")[0];
  if (ins && Array.isArray(ins.sol_keys) && ins.sol_keys.length) {
    insight_sol = ins.sol_keys[(sol - 1) % ins.sol_keys.length];
    const d = ins[insight_sol] || {};
    if (d.AT && Number.isFinite(d.AT.av)) weather = { temp_avg_c: Math.round(d.AT.av * 10) / 10, source: "InSight/AT" };
    if (d.HWS && Number.isFinite(d.HWS.av)) wind = { speed_avg_ms: Math.round(d.HWS.av * 10) / 10, source: "InSight/HWS" };
  }
}

// ---- Biblioteca de imagens da NASA (pagina = Sol, entao muda a cada Sol) ----
let photo = null;
{
  const lib = all("NASA Images")[0];
  const item = lib && lib.collection && lib.collection.items && lib.collection.items[0];
  if (item && item.data && item.data[0]) {
    const info = item.data[0];
    const url = (item.links || []).find(l => l.rel === "preview" && String(l.href).startsWith("https://"));
    if (url) photo = { id: info.nasa_id, title: info.title, description: (info.description || "").slice(0, 400), credit: info.photographer || info.center || "NASA", url: url.href };
  }
}

const severity = (flare && flare.class === "X") || (mars_impact && mars_impact.level === "direct") ? "alert"
  : (flare && flare.class === "M") || (mars_impact && mars_impact.level === "glancing_blow") ? "attention" : "calm";

return [{ json: { sol, earth_date: date, insight_sol, facts: { flare, cme, mars_impact, weather, wind, severity }, apod, photo } }];

const r = $input.first().json;
const content = r.choices && r.choices[0] && r.choices[0].message && r.choices[0].message.content;
if (!content) throw new Error("empty groq response");
const parsed = JSON.parse(content);
const mood = ["happy", "worried", "excited", "proud"].includes(parsed.mood) ? parsed.mood : "happy";
return [{ json: { text: String(parsed.text || "").slice(0, 600), mood } }];
